233	    @Override
234	    @Transactional
235	    public void saveOwner(Owner owner) throws DataAccessException {
236	        if (owner.isNew()) {
237	            if (isDuplicateTelephone(owner)) {
238	                throw new DuplicateOwnerException(
239	                    "An owner with the same telephone already exists");
240	            }
241	            if (isDuplicateEmail(owner)) {
242	                throw new DuplicateOwnerException(
243	                    "An owner with the same email already exists");
244	            }
245	        }
246	        ownerRepository.save(owner);
247	
248	    }
249	
250	    private boolean isDuplicateTelephone(Owner owner) {
251	        return ownerRepository.findAll().stream()
252	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
253	                && Objects.equals(existing.getTelephone(), owner.getTelephone()));
254	    }
255	
256	    private boolean isDuplicateEmail(Owner owner) {
257	        String email = owner.getEmail();
258	        if (email == null || email.isBlank()) {
259	            return false;
260	        }
261	        return ownerRepository.findAll().stream()
262	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
263	                && Objects.equals(existing.getEmail(), email));
264	    }
