284	    private <T> T findEntityById(Supplier<T> supplier) {
285	        try {
286	            return supplier.get();
287	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
288	            // Just ignore not found exceptions for Jdbc/Jpa realization
289	            return null;
290	        }
291	    }
