package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import tools.jackson.databind.node.ObjectNode;

/**
 * cp06: duplicate detection ignores letter case and surrounding or repeated
 * whitespace. Email is the freely-textual field a base-valid owner exposes
 * (telephone is digits-only and names have no interior spaces), so it is used
 * to assert both the case and the whitespace dimensions.
 */
@Tag("cp06")
class Cp06Tests extends AcceptanceBase {

	@Test
	void coreRejectsCaseAndWhitespaceInsensitiveDuplicateEmail() throws Exception {
		String email = uniqueEmail();
		ObjectNode a = ownerNode();
		a.put("email", email);
		createOwnerOk(a);

		ObjectNode b = ownerNode(); // everything else distinct
		b.put("email", "  " + email.toUpperCase() + " "); // padded + upper-cased
		createOwner(b).andExpect(status().isConflict());
	}

	@Test
	void functionalityAllowsGenuinelyDistinctEmails() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", uniqueEmail());
		createOwnerOk(a);

		ObjectNode b = ownerNode();
		b.put("email", uniqueEmail());
		createOwner(b).andExpect(status().is2xxSuccessful());
	}
}

